    using babel::JSON::readJSON;
    using babel::JSON::writeJSON;
    using babel::JSON::interpretJSON;

    template <class CharT>
    void
    interpretJSON( const babel::JSON::parser::Value &theJSONValue, Item &theValue) {
        using StringType = std::basic_string<CharT>;

        static const CharT * const theRequiredFields[] = {
            BABEL_JSON_PARSER_STRING_LITERAL(CharT,"name"),
            BABEL_JSON_PARSER_STRING_LITERAL(CharT,"price"),
            BABEL_JSON_PARSER_STRING_LITERAL(CharT,"dims"),
            BABEL_JSON_PARSER_STRING_LITERAL(CharT,"points"),
            BABEL_JSON_PARSER_STRING_LITERAL(CharT,"byName"),
            BABEL_JSON_PARSER_STRING_LITERAL(CharT,"byId"),
            BABEL_JSON_PARSER_STRING_LITERAL(CharT,"flags"),
            BABEL_JSON_PARSER_STRING_LITERAL(CharT,"level"),
            BABEL_JSON_PARSER_STRING_LITERAL(CharT,"ptr")
        };
        bool       theUsedRequiredFields[sizeof(theRequiredFields)/sizeof(theRequiredFields[0])]{};

        StringType theExtraFields;
        #ifndef __clang_analyzer__
            Item theActual;
        #else
            Item theActual {};
        #endif

        for (const auto &thePair : BABEL_JSON_PARSER_UPCAST( Object<std::basic_string<CharT>>,theJSONValue ).itsValue) {
            if (thePair.first == theRequiredFields[0]) {
                interpretJSON<CharT>( thePair.second, theActual.name );
                theUsedRequiredFields[0] = true;
            }
            else if (thePair.first == theRequiredFields[1]) {
                interpretJSON<CharT>( thePair.second, theActual.price );
                theUsedRequiredFields[1] = true;
            }
            else if (thePair.first == BABEL_JSON_PARSER_STRING_LITERAL(CharT,"qty")) {
                interpretJSON<CharT>( thePair.second, theActual.qty );
            }
            else if (thePair.first == theRequiredFields[2]) {
                interpretJSON<CharT>( thePair.second, theActual.dims );
                theUsedRequiredFields[2] = true;
            }
            else if (thePair.first == theRequiredFields[3]) {
                interpretJSON<CharT>( thePair.second, theActual.points );
                theUsedRequiredFields[3] = true;
            }
            else if (thePair.first == theRequiredFields[4]) {
                interpretJSON<CharT>( thePair.second, theActual.byName );
                theUsedRequiredFields[4] = true;
            }
            else if (thePair.first == theRequiredFields[5]) {
                interpretJSON<CharT>( thePair.second, theActual.byId );
                theUsedRequiredFields[5] = true;
            }
            else if (thePair.first == BABEL_JSON_PARSER_STRING_LITERAL(CharT,"color")) {
                interpretJSON<CharT>( thePair.second, theActual.color );
            }
            else if (thePair.first == theRequiredFields[6]) {
                interpretJSON<CharT>( thePair.second, theActual.flags );
                theUsedRequiredFields[6] = true;
            }
            else if (thePair.first == theRequiredFields[7]) {
                interpretJSON<CharT>( thePair.second, theActual.level );
                theUsedRequiredFields[7] = true;
            }
            else if (thePair.first == theRequiredFields[8]) {
                interpretJSON<CharT>( thePair.second, theActual.ptr );
                theUsedRequiredFields[8] = true;
            }
            else {
                if (theExtraFields.empty()) { theExtraFields.append(BABEL_JSON_PARSER_STRING_LITERAL(CharT,"unknown field(s):")); }
                theExtraFields.append(BABEL_JSON_PARSER_STRING_LITERAL(CharT," ")).append(thePair.first);
            }
        }

        StringType theMissingFields;

        for (std::size_t i = 0; i < sizeof(theUsedRequiredFields)/sizeof(theUsedRequiredFields[0]); i++) {
            if (!theUsedRequiredFields[i]) {
                if (theMissingFields.empty()) { theMissingFields.append(BABEL_JSON_PARSER_STRING_LITERAL(CharT,"missing field(s):")); }
                theMissingFields.append(BABEL_JSON_PARSER_STRING_LITERAL(CharT," ")).append(theRequiredFields[i]);
            }
        }


        if (!theMissingFields.empty() || !theExtraFields.empty()) {
            using CharTraits = ::babel::JSON::parser::CharTraits<char>;
            if (!theMissingFields.empty() && !theExtraFields.empty()) { theMissingFields.append(BABEL_JSON_PARSER_STRING_LITERAL(CharT,", ")); }
            throw std::invalid_argument(theJSONValue->getLocation() + "Type ::shop::Item has errors: " + CharTraits::adjust(theMissingFields) + CharTraits::adjust(theExtraFields) );
        }

    #pragma GCC diagnostic push
    #pragma GCC diagnostic ignored "-Wmaybe-uninitialized"
        theValue = std::move(theActual);
    #pragma GCC diagnostic pop
    }

    template <class CharT, class Traits>
    std::basic_ostream<CharT,Traits>&
    writeJSON( std::basic_ostream<CharT,Traits>&theStream, const Item &theValue, babel::JSON::Indent theIndent ) {
        static const CharT * const theLabelSet[2][11] = {
            { 
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"name\":"),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"price\":"),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"qty\":"),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"dims\":"),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"points\":"),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"byName\":"),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"byId\":"),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"color\":"),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"flags\":"),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"level\":"),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"ptr\":")
            },
            {
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"name\"  : "),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"price\" : "),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"qty\"   : "),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"dims\"  : "),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"points\": "),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"byName\": "),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"byId\"  : "),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"color\" : "),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"flags\" : "),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"level\" : "),
                BABEL_JSON_PARSER_STRING_LITERAL(CharT,"\"ptr\"   : ")
            }
        };
        const auto theContentIndent = theIndent.next();
        const auto theNextIndent    = theContentIndent.next();
        const auto theLabels        = theLabelSet[theIndent.isActive()];
        theStream << '{' << theContentIndent;
        writeJSON( theStream << theLabels[ 0], theValue.name,   theNextIndent ) << ',' << theContentIndent;
        writeJSON( theStream << theLabels[ 1], theValue.price,  theNextIndent ) << ',' << theContentIndent;
        writeJSON( theStream << theLabels[ 2], theValue.qty,    theNextIndent ) << ',' << theContentIndent;
        writeJSON( theStream << theLabels[ 3], theValue.dims,   theNextIndent ) << ',' << theContentIndent;
        writeJSON( theStream << theLabels[ 4], theValue.points, theNextIndent ) << ',' << theContentIndent;
        writeJSON( theStream << theLabels[ 5], theValue.byName, theNextIndent ) << ',' << theContentIndent;
        writeJSON( theStream << theLabels[ 6], theValue.byId,   theNextIndent ) << ',' << theContentIndent;
        writeJSON( theStream << theLabels[ 7], theValue.color,  theNextIndent ) << ',' << theContentIndent;
        writeJSON( theStream << theLabels[ 8], theValue.flags,  theNextIndent ) << ',' << theContentIndent;
        writeJSON( theStream << theLabels[ 9], theValue.level,  theNextIndent ) << ',' << theContentIndent;
        writeJSON( theStream << theLabels[10], theValue.ptr,    theNextIndent ) << theIndent;
        theStream << '}';
        return theStream;
    }


